// Baca CONFIG (key/value) -> objek cfg + gate jam etis WIB + clamp parameter beban
const rows = $input.all().map(i => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key || r.Key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : ((r.Value !== undefined && r.Value !== null) ? r.Value : '');
}
const num = (k, d) => { const n = Number(cfg[k]); return isNaN(n) ? d : n; };
const yes = (k, dflt) => {
  const v = String(cfg[k] === undefined || cfg[k] === '' ? dflt : cfg[k]).trim().toUpperCase();
  return v === 'Y' || v === 'YES' || v === 'TRUE' || v === '1';
};

let templates = [];
try { templates = JSON.parse(cfg.followup_templates || '[]'); } catch (e) { templates = []; }
if (!Array.isArray(templates)) templates = [];

const openH = num('followup_open_hour', 8);
const closeH = num('followup_close_hour', 21);
const wibHour = Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', hour12: false }).format(new Date()));

// Di luar jam etis atau template kosong -> stop; trigger jam berikutnya coba lagi.
// Kandidat yang "ketinggalan" otomatis terkirim di slot berikutnya (antrian tidak hilang).
if (wibHour < openH || wibHour >= closeH) return [];
// AI aktif = composer Haiku yang merangkai kalimat dari kolom STATS "konteks".
// Template lama TIDAK dihapus - dipakai kalau AI sengaja dimatikan lewat CONFIG.
const aiEnabled = yes('followup_ai_enabled', 'Y');
const aiDryRun  = yes('followup_ai_dry_run', 'N');
// Dulu: seluruh run mati kalau followup_templates kosong. Sekarang template
// hanya wajib saat AI mati - kalau tidak, sheet template kosong ikut
// mematikan mode AI yang sebenarnya tidak membutuhkannya.
if (!aiEnabled && !templates.length) return [];

// Clamp agar salah konfigurasi tidak berubah jadi blast massal.
let minDelay = num('followup_min_delay_sec', 20);
let maxDelay = num('followup_max_delay_sec', 45);
if (minDelay < 3) minDelay = 3;                    // jaga jarak minimum (anti-spam)
if (maxDelay < minDelay) maxDelay = minDelay + 5;
let maxPerRun = num('followup_max_per_run', 20);
if (maxPerRun < 1) maxPerRun = 1;
if (maxPerRun > 300) maxPerRun = 300;              // plafon keras: 1 run selalu << 1 jam

// Reset penghitung kegagalan compose untuk run ini; dibaca "Report FU Run"
// di ujung loop. Pola static data sama dengan Rate Limiter LID di workflow Main.
try { $getWorkflowStaticData('global').fu_ai_fail = []; } catch (e) {}

return [{ json: {
  config: {
    kirimi_user_code: String(cfg.kirimi_user_code || '').trim(),
    kirimi_secret: String(cfg.kirimi_secret || '').trim(),
    kirimi_device_id: String(cfg.kirimi_device_id || '').trim(),
    admin_phone: String(cfg.admin_phone || '').trim(),
    exclude_numbers: [cfg.admin_phone, cfg.admin_phone_display, cfg.field_team_phone, cfg.media_team_phone]
      .map(v => String(v || '').replace(/\D/g, '')).filter(Boolean),
    // MODE UJI. Kalau followup_test_numbers diisi, HANYA nomor-nomor itu yang
    // boleh jadi kandidat - lead sungguhan tidak tersentuh sama sekali. Kosongkan
    // untuk kembali normal. Berlaku baik saat dry run maupun kirim sungguhan.
    test_numbers: String(cfg.followup_test_numbers || '')
      .split(/[,;\s]+/).map(v => v.replace(/\D/g, '')).filter(Boolean),
    followup_max: num('followup_max', 0),
    followup_interval_hours: num('followup_interval_hours', 72),
    templates: templates,
    min_delay: minDelay,
    max_delay: maxDelay,
    max_per_run: maxPerRun,
    open_hour: openH,
    close_hour: closeH,
    ai_enabled: aiEnabled,
    ai_dry_run: aiDryRun
  },
  now_epoch: Math.floor(Date.now() / 1000)
} }];

// Saring baris STATS -> user layak follow-up sekarang, lalu BATASI jumlah per-run.
// Cap ini yang bikin workflow sanggup skala besar: 1000 nomor otomatis dicicil lintas jam/hari,
// bukan diblast dalam satu eksekusi.
const base = $('Parse Config FU').first().json;
const cfg = base.config;
const now = base.now_epoch;
const intervalSec = (cfg.followup_interval_hours || 72) * 3600;

// Jam WIB sekarang -> hitung sisa waktu sampai jam tutup (batas aman anti-bleed).
const wibParts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
const wibHour = Number((wibParts.find(p => p.type === 'hour') || {}).value || 0);
const wibMin = Number((wibParts.find(p => p.type === 'minute') || {}).value || 0);

const modeUji = Array.isArray(cfg.test_numbers) && cfg.test_numbers.length > 0;
if (modeUji) console.warn('MODE UJI AKTIF - hanya ' + cfg.test_numbers.join(', ') + ' yang akan di-follow-up');

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const row = item.json;
  const noWa = String(row['No WA'] || '').trim();
  if (!noWa) continue;
  const digits = noWa.replace(/\D/g, '');
  if (!digits) continue;
  if (seen.has(digits)) continue;                              // dedupe kalau STATS ada baris ganda
  // Didaftarkan SEBELUM filter lain. Waktu seen.add ada di ujung (hanya untuk baris yang
  // lolos), baris bot_mode=OFF keluar tanpa mendaftar -> baris KEMBARANNYA yang ON ikut
  // lolos, jadi mematikan bot untuk lead itu tidak berlaku. Gagal diam, tanpa error.
  seen.add(digits);
  // 'No WA' yang isinya sama persis dengan 'lid': nomor telepon tidak pernah tertangkap
  // (kontak LID-only / privacy). Dikirimi pesan pun tidak sampai ke siapa pun.
  const lidDigits = String(row['lid'] || '').replace(/\D/g, '');
  if (lidDigits && digits === lidDigits) continue;
  if (digits.length < 10 || digits.length > 15) continue;      // bukan MSISDN
  // MODE UJI menang atas exclude_numbers: kalau tidak, nomor uji yang kebetulan
  // terdaftar sebagai admin/tim akan tersaring diam-diam dan hasilnya 0 kandidat
  // tanpa penjelasan.
  if (modeUji) {
    if (!cfg.test_numbers.includes(digits)) continue;          // di luar daftar uji
  } else if (cfg.exclude_numbers.includes(digits)) continue;   // nomor tim/admin
  if (/^off$/i.test(String(row['bot_mode'] || '').trim())) continue;             // dipegang manusia
  if (/^scheduled$/i.test(String(row['survey_status'] || '').trim())) continue;  // goal tercapai
  if (Number(row['Counter'] || 0) < 1) continue;               // belum pernah chat

  const lastReply = Number(row['last_reply_ts'] || 0);
  if (!lastReply) continue;                                    // belum pernah dibalas bot
  if (now - lastReply < intervalSec) continue;                 // masih hangat, jangan ganggu

  const lastFu = Number(row['last_follow_up_ts'] || 0);
  if (lastFu && now - lastFu < intervalSec) continue;          // belum jatuh tempo follow-up berikutnya

  const fuCount = Number(row['follow_up_count'] || 0);
  if (cfg.followup_max > 0 && fuCount >= cfg.followup_max) continue;  // 0 = tanpa batas

  // Personalisasi: {nama}/{name} -> nama depan (kalau template pakai placeholder).
  // Kalau template polos tanpa placeholder, tidak ada yang berubah (aman).
  const namaRaw = String(row['Nama'] || '').trim();
  let msg = String(cfg.templates[fuCount % cfg.templates.length] || '');
  // Placeholder {nama} SELALU jadi 'Kak'. Kolom 'Nama' berisi push name akun WA
  // yang sering bukan nama orang - menyapa salah lebih merusak daripada netral.
  msg = msg.replace(/\{\s*(nama|name)\s*\}/gi, 'Kak');

  out.push({ json: {
    no_wa: noWa,
    lid: String(row['lid'] || '').trim(),
    nama: namaRaw,
    follow_up_count: fuCount,
    prev_last_fu: lastFu || '',                                 // untuk rollback kalau kirim gagal
    last_reply_ts: lastReply,
    message: msg,
    // -- bahan composer AI (2026-08-27) ------------------------------------
    // Semua diambil dari baris STATS yang SUDAH di tangan run ini, jadi tidak
    // ada pembacaan Sheets tambahan dan tidak ada tambahan kuota.
    days_idle: Math.floor((now - lastReply) / 86400),
    konteks: String(row['konteks'] || '').trim(),
    last_msgs: String(row['last_msgs'] || '').trim(),
    unit_interest: String(row['unit_interest'] || '').trim(),
    budget_range: String(row['budget_range'] || '').trim(),
    lokasi_kerja: String(row['lokasi_kerja'] || '').trim(),
    nama_lengkap: String(row['nama_lengkap'] || '').trim(),
    lead_source: String(row['lead_source'] || '').trim(),
    pesan_pertama: String(row['Pesan Pertama'] || '').trim().slice(0, 200)
  } });
}

// Prioritas antrian: yang belum pernah di-follow-up dulu, lalu yang paling lama tidak dibalas.
out.sort((a, b) => {
  const af = Number(a.json.follow_up_count), bf = Number(b.json.follow_up_count);
  if (af !== bf) return af - bf;
  return Number(a.json.last_reply_ts) - Number(b.json.last_reply_ts);
});

// Batas per-run = min(cap config, kapasitas waktu tersisa sebelum jam tutup).
const avgDelay = ((cfg.min_delay + cfg.max_delay) / 2) + 4;     // +4s: latency Kirimi + 1 panggilan Haiku per kandidat
const minutesToClose = Math.max(0, (cfg.close_hour - wibHour) * 60 - wibMin);
const capByTime = Math.floor((minutesToClose * 60) / avgDelay);
const cap = Math.max(0, Math.min(cfg.max_per_run, capByTime));

const hasil = out.slice(0, cap);
// Bawa ukuran antrian sebenarnya ke laporan. Tanpa ini '20 dari 20' terbaca seolah cuma
// ada 20 lead, padahal 20 itu cap per-run dan backlog di belakangnya jauh lebih besar.
for (const h of hasil) { h.json.antrian_total = out.length; h.json.cap_per_run = cap; }
if (modeUji && hasil.length === 0) {
  console.warn('MODE UJI: 0 kandidat. Nomor uji ada di STATS? Cek Counter >= 1, '
    + 'last_reply_ts terisi dan sudah lewat interval, bot_mode bukan OFF, '
    + 'survey_status bukan SCHEDULED, last_follow_up_ts kosong.');
}
return hasil;

// ====================================================================
// BUILD FU PROMPT (2026-08-27)
// Dijalankan SESUDAH Claim STATS FU - anti-dobel tetap utuh: nomornya sudah
// diklaim sebelum satu token pun dibakar.
// ====================================================================
const cfg = $('Parse Config FU').first().json.config;
const c = $('Loop Kandidat').first().json;

// Nama SENGAJA tidak dipakai. Kolom STATS 'Nama' berisi push name akun WA yang
// sering bukan nama orang ('dawwonnu24', nama toko, nama pasangan). Menyapa dengan
// nama yang salah lebih merusak kepercayaan daripada sekadar 'Kak'.
const fuKe = Number(c.follow_up_count || 0) + 1;

// Nada menyesuaikan berapa kali orang ini sudah dikejar. followup_max = 0
// (tanpa batas) berarti angka ini bisa jadi belasan - makin tinggi, makin
// pelan, supaya AI tidak jadi mesin desak.
let tahap;
if (fuKe <= 2) {
  tahap = 'AWAL - lanjutkan pembicaraan dengan hangat, wajar kalau menawarkan langkah konkret.';
} else if (fuKe <= 5) {
  tahap = 'MENENGAH - lebih ringan. Jangan mengulang ajakan yang sudah pernah dia lewatkan.';
} else {
  tahap = 'LANJUT - SOFT. Beri ruang, akui dia mungkin sedang sibuk atau belum tertarik, JANGAN mendesak, dan JANGAN mengajak survey lagi kecuali konteks menunjukkan minat baru.';
}

// -- SAMARKAN BAHAN PROMPT (2026-09-13) --------------------------------------
// Guard "Validate FU Message" menolak pesan yang memuat angka harga/DP/cicilan/
// tenor, URL, nomor telepon, atau nama lead. Kalau bahan prompt SENDIRI memuat pola
// itu (mis. konteks "tenor 3 tahun"), AI ikut menulisnya, pesan ditolak, dan lead
// yang sama gagal di SETIAP run karena konteksnya tidak berubah sampai dia chat lagi
// (kejadian nyata: 6289635089520, 12-13 Sep 2026). Angka disamarkan di sini supaya
// AI tidak punya angka untuk disalin. Hanya bahan prompt - tidak ada yang ditulis
// balik ke STATS.
// WAJIB tetap SUPERSET dari pola guard di "Validate FU Message": jaring terakhir
// di bawah memakai pola guard persis, jadi kalau guard diubah, ubah juga di sini.
const GUARD_SAMAR = [
  { re: /\d{1,3}([.,]\d{3})+/g, ganti: '[angka]' },
  { re: /\b\d+([.,]\d+)?\s*(jt|juta|rb|ribu|m|miliar|milyar)\b/gi, ganti: '[angka]' },
  { re: /\bRp\s*\.?\s*\d/gi, ganti: '[angka]' },
  { re: /\d+\s*%/g, ganti: '[angka]' },
  { re: /\b\d+\s*tahun\b/gi, ganti: '[angka]' },
  { re: /(https?:|www\.|wa\.me|\.com\b|\.id\b)/gi, ganti: '[link]' },
  { re: /\b0\d{8,}\b|\b62\d{8,}\b/g, ganti: '[nomor]' }
];
// Sama dengan daftar UMUM di guard nama "Validate FU Message".
const UMUM_NAMA = ['persada','cisoka','residence','rumah','unit','tipe','subsidi','komersil',
  'komersial','info','admin','marketing','property','properti','sales','survey','kpr',
  'pak','bapak','ibu','kak','mas','mbak','bu','yang','saya','kami','anda'];
const namaLead = String((c.nama_lengkap || '') + ' ' + (c.nama || ''))
  .split(/[^A-Za-z]+/)
  .filter(w => w.length >= 3 && UMUM_NAMA.indexOf(w.toLowerCase()) === -1)
  .map(w => w.toLowerCase());

const samarkan = s => {
  let t = String(s || '');
  if (!t) return t;
  // Bentuk utuh dulu (termasuk rentang "15-30 tahun", "10, 15, 20 tahun"),
  // supaya yang tersisa tidak berupa potongan seperti "15-[angka]".
  t = t
    .replace(/\S*(https?:|www\.|wa\.me|\.com\b|\.id\b)\S*/gi, '[link]')
    .replace(/\+?\b(0|62)\d{8,}\b/g, '[nomor]')
    .replace(/\bRp\s*\.?\s*\d+([.,]\d+)*(\s*(jt|juta|rb|ribu|k|m|miliar|milyar)\b)?/gi, '[angka]')
    .replace(/\b\d+([.,]\d+)?(\s*(-|–|—|\/|,|s\.?\s*d\.?|sampai|hingga|atau|dan)\s*\d+([.,]\d+)?)*\s*(tahun|thn|th)\b/gi, '[angka]')
    .replace(/\b\d+([.,]\d+)?(\s*(-|–|—|\/|s\.?\s*d\.?|sampai|hingga|atau|dan)\s*\d+([.,]\d+)?)*\s*(jt|juta|rb|ribu|k|m|miliar|milyar)\b/gi, '[angka]')
    .replace(/\d{1,3}([.,]\d{3})+([.,]\d+)?/g, '[angka]')
    .replace(/\d+([.,]\d+)?(\s*(-|–|—|\/|s\.?\s*d\.?|sampai|hingga|atau|dan)\s*\d+([.,]\d+)?)*\s*%/g, '[angka]');
  if (namaLead.length) {
    t = t.split(/([^A-Za-z]+)/)
      .map(tok => (namaLead.indexOf(tok.toLowerCase()) !== -1 ? '[nama]' : tok))
      .join('');
  }
  // Jaring terakhir: apa pun yang masih cocok dengan pola guard persis ikut disamarkan.
  for (let i = 0; i < 3; i++) {
    let sisa = false;
    for (const g of GUARD_SAMAR) {
      if (t.search(g.re) !== -1) { sisa = true; t = t.replace(g.re, g.ganti); }
    }
    if (!sisa) break;
  }
  return t;
};

// "LANGKAH BERIKUT" di konteks adalah RENCANA untuk VIRA di chat, belum dikerjakan.
// Diberikan ke composer follow-up, AI menulisnya seolah sudah terjadi ("saya sudah
// cek ke tim kami ..."), padahal tidak ada yang mengecek. Baris itu tidak dikirim ke AI.
const buangLangkahBerikut = s => {
  let buang = false;
  return String(s || '').split('\n').filter(line => {
    const m = line.match(/^\s*([A-Za-z][A-Za-z _\/]{2,30}?)\s*:/);
    if (m) buang = /^langkah\s+berikut/i.test(m[1]);
    return !buang;
  }).join('\n').trim();
};

return [{ json: {
  ai_enabled: !!cfg.ai_enabled,
  ai_dry_run: !!cfg.ai_dry_run,
  fu_ke: fuKe,
  fu_tahap: tahap,
  fu_hari: Number(c.days_idle || 0),
  fu_konteks: samarkan(buangLangkahBerikut(c.konteks)),
  fu_last_msgs: samarkan(c.last_msgs),
  fu_unit: samarkan(c.unit_interest),
  fu_budget: samarkan(c.budget_range),
  fu_lokasi: samarkan(c.lokasi_kerja),
  fu_sumber: samarkan(c.lead_source),
  fu_pesan_pertama: samarkan(c.pesan_pertama)
}}];

// ====================================================================
// VALIDATE FU MESSAGE (2026-08-27)
// Guard deterministik, meniru semangat PRICE GUARD di node "Process All"
// workflow Main: prompt boleh melarang, tapi yang MENJAMIN adalah kode.
// Melanggar -> throw -> error output -> Catat Kegagalan AI -> rollback klaim.
// Sesuai keputusan: nomor yang gagal DILEWATI, bukan dikirimi template.
// ====================================================================
const cfg = $('Parse Config FU').first().json.config;
const c = $('Loop Kandidat').first().json;
const p = $('Build FU Prompt').first().json;

const bersihkan = s => String(s || '')
  .replace(/\[[^\]]*\]/g, ' ')     // buang tag [SEND_MEDIA] dsb kalau bocor
  .replace(/[*`#]/g, '')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

let pesan = '';

if (p.ai_enabled) {
  try {
    const s = $input.first().json;
    pesan = (s.content && s.content[0] && s.content[0].text) || s.text || '';
  } catch (e) {}
  pesan = bersihkan(pesan);

  const tolak = [];
  if (pesan.length < 20) tolak.push('terlalu pendek atau kosong');
  if (pesan.length > 400) tolak.push('terlalu panjang (' + pesan.length + ' char)');
  if (/\d{1,3}([.,]\d{3})+/.test(pesan)) tolak.push('nominal berformat ribuan');
  if (/\b\d+([.,]\d+)?\s*(jt|juta|rb|ribu|m|miliar|milyar)\b/i.test(pesan)) tolak.push('nominal singkat');
  if (/\bRp\s*\.?\s*\d/i.test(pesan)) tolak.push('menyebut Rp');
  if (/\d+\s*%/.test(pesan)) tolak.push('persentase');
  if (/\b\d+\s*tahun\b/i.test(pesan)) tolak.push('tenor');
  if (/(https?:|www\.|wa\.me|\.com\b|\.id\b)/i.test(pesan)) tolak.push('URL');
  if (/\b0\d{8,}\b|\b62\d{8,}\b/.test(pesan)) tolak.push('nomor telepon');

  // Guard nama. Prompt sudah melarang, tapi yang menjamin adalah kode.
  // (a) pola sapaan bernama: "Kak Novi", "Kak Kris".
  if (/\bKak\s+[A-Z][a-z]{2,}/.test(pesan)) tolak.push('menyapa pakai nama');
  // (b) nama yang benar-benar tersimpan untuk lead ini, di mana pun ia muncul.
  //     Kata umum/merek dikecualikan supaya push name seperti "Cisoka Property"
  //     tidak membuat SEMUA pesan ditolak.
  const UMUM = ['persada','cisoka','residence','rumah','unit','tipe','subsidi','komersil',
    'komersial','info','admin','marketing','property','properti','sales','survey','kpr',
    'pak','bapak','ibu','kak','mas','mbak','bu','yang','saya','kami','anda'];
  const kandidatNama = String((c.nama_lengkap || '') + ' ' + (c.nama || ''))
    .split(/[^A-Za-z]+/)
    .filter(w => w.length >= 3 && UMUM.indexOf(w.toLowerCase()) === -1);
  for (const w of kandidatNama) {
    const aman = w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (new RegExp('\\b' + aman + '\\b', 'i').test(pesan)) {
      tolak.push('menyebut nama lead (' + w + ')');
      break;
    }
  }

  // (2026-09-13) Klaim sudah mengecek/menanyakan/mengonfirmasi ke TIM atau pihak lain,
  // atau sudah menelepon - hal yang tidak pernah dilakukan siapa pun. Prompt melarang, tapi
  // terbukti tetap ditulis AI ("saya sudah cek ke tim kami", "sudah saya tanyakan ke tim";
  // lead 6289635089520, 7 run berturut-turut, 12-13 Sep).
  // SENGAJA sempit: "saya sudah kirimkan daftar persyaratannya" atau "seperti yang sudah
  // saya sampaikan" sering BENAR (konteks STATS mencatat "Vira sudah kirim ...") dan
  // tidak boleh ikut ditolak. Subjek wajib saya/kami/tim supaya "Kakak sudah cek?" lolos.
  if (/\b(saya|aku|kami|vira)\s+(juga\s+|pun\s+|tadi\s+|kemarin\s+)?(sudah|udah|telah|barusan)\s+(sempat\s+|coba\s+|juga\s+|langsung\s+)?(cek|cekin|cekkan|mengecek|ngecek|periksa|memeriksa|tanya|tanyakan|menanyakan|nanya|nanyain|konfirmasi|konfirmasikan|mengonfirmasi|mengonfirmasikan|mengkonfirmasi|koordinasi|koordinasikan|berkoordinasi|mengoordinasikan|diskusi|diskusikan|berdiskusi|mendiskusikan|hubungi|menghubungi|kontak|mengontak|pastikan|memastikan|minta|meminta|mintakan|carikan|mencarikan)\b((\s+[^\s.?!,]+){0,4}?\s+(ke|kepada|dengan|sama|pada|oleh)\s+|\s+)(tim|marketing|admin|atasan|kantor|developer|pihak|bagian|manajemen|management|bank)\b/i.test(pesan)
    || /\b(sudah|udah|telah|barusan)\s+(saya|aku|kami)\s+(cek|cekkan|periksa|tanya|tanyakan|konfirmasi|konfirmasikan|koordinasikan|diskusikan|hubungi|kontak|pastikan|mintakan|carikan)\b((\s+[^\s.?!,]+){0,4}?\s+(ke|kepada|dengan|sama|pada)\s+|\s+)(tim|marketing|admin|atasan|kantor|developer|pihak|bagian|manajemen|management|bank)\b/i.test(pesan)
    || /\b(tim|marketing|admin|atasan|developer|pihak|bagian|manajemen)\b(\s+[A-Za-z]+){0,2}\s+(juga\s+)?(sudah|udah|telah|barusan)\s+(sempat\s+|coba\s+|juga\s+|langsung\s+)?(cek|mengecek|periksa|memeriksa|konfirmasi|mengonfirmasi|mengkonfirmasi|koordinasi|berkoordinasi|diskusi|berdiskusi|mendiskusikan|pastikan|memastikan|siapkan|menyiapkan|hitung|menghitung|hubungi|menghubungi|carikan|mencarikan|setujui|menyetujui)\b/i.test(pesan)
    || /\b(sudah|udah|telah)\s+di(cek|periksa|tanyakan|konfirmasi|konfirmasikan|koordinasikan|diskusikan|pastikan|setujui)\s+(oleh|dari|ke|dengan|sama|bersama)\s+(pihak\s+|bagian\s+)?(tim|kami|marketing|admin|atasan|developer|manajemen)\b/i.test(pesan)
    || /\b(saya|aku|kami|tim|vira)\s+(juga\s+|pun\s+|tadi\s+|kemarin\s+)?(sudah|udah|telah|barusan)\s+(sempat\s+|coba\s+)?(telepon|menelepon|telpon|nelpon|menelpon)\b/i.test(pesan)) {
    tolak.push('klaim sudah melakukan');
  }

  // (2026-09-13) Keluaran AI KOSONG = anomali model/API, bukan soal isi konteks: tetap
  // pakai pesan error lama persis, supaya perilakunya juga tetap lama (klaim di-rollback,
  // dicoba lagi run berikutnya) dan tidak menunda lead 48 jam karena gangguan sesaat.
  if (tolak.length && !pesan) {
    throw new Error('FU_AI_INVALID: ' + tolak.join(', ') + ' :: ' + pesan.slice(0, 160));
  }
  if (tolak.length) {
    // (2026-09-13) Satu baris, TANPA titik dua. Formatter error node Code n8n hanya
    // membawa baris pertama dan memotong di titik dua (versi live: hanya menyisakan teks
    // SETELAH titik dua terakhir - itu sebabnya notif lama berisi potongan pesan tanpa
    // alasan). Penanda FU_AI_DITOLAK_GUARD wajib sampai utuh ke "Rollback STATS FU (AI)"
    // (nomor DITUNDA ke jadwal berikutnya, bukan diulang tiap jam) dan "Report FU Run".
    // Maks 150 char: "Catat Kegagalan AI" memotong 180 SESUDAH n8n menambah "[line N]".
    const info = ('FU_AI_DITOLAK_GUARD (' + tolak.join(', ') + ') >> ' + pesan)
      .replace(/[:\r\n]+/g, ' ')
      .replace(/\s{2,}/g, ' ')
      .slice(0, 150);
    throw new Error(info);
  }
} else {
  // followup_ai_enabled = N -> kembali ke template rotasi lama.
  pesan = String(c.message || '').trim();
  if (!pesan) throw new Error('FU_AI_INVALID: AI dimatikan tapi template kosong');
}

// Dry run: pesan tetap disusun sungguhan, tapi dikirim ke admin - bukan lead.
const dry = !!p.ai_dry_run;
const target = dry ? String(cfg.admin_phone || '').trim() : String(c.no_wa || '').trim();
if (!target) throw new Error('FU_AI_INVALID: nomor tujuan kosong');

const teks = dry
  ? ('[DRY RUN -> ' + c.no_wa + ' | FU ke-' + p.fu_ke + ' | idle ' + p.fu_hari + 'h]\n\n' + pesan)
  : pesan;

return [{ json: {
  target_phone: target,
  final_message: teks,
  dry_run: dry,
  no_wa: c.no_wa
}}];

// ====================================================================
// CATAT KEGAGALAN AI (2026-08-27)
// Compose gagal, atau hasilnya ditolak guard. Sesuai keputusan: nomor ini
// DILEWATI, klaim dikembalikan, dicoba lagi run berikutnya.
// Dicatat di static data supaya "Report FU Run" bisa melapor SEKALI di ujung
// run - bukan satu notif WA per kegagalan.
// ====================================================================
const c = $('Loop Kandidat').first().json;

let alasan = '';
try {
  const e = $input.first().json;
  // Item error n8n bisa berbentuk string ATAU objek {message, description}.
  // String(objek) menghasilkan "[object Object]" - laporan jadi tidak berguna.
  const raw = e.error !== undefined ? e.error : e.message;
  alasan = (raw && typeof raw === 'object')
    ? String(raw.message || raw.description || JSON.stringify(raw))
    : String(raw || '');
  alasan = alasan.slice(0, 180);
} catch (err) {}
if (!alasan) alasan = 'tidak diketahui';

try {
  const sd = $getWorkflowStaticData('global');
  if (!Array.isArray(sd.fu_ai_fail)) sd.fu_ai_fail = [];
  sd.fu_ai_fail.push({ no_wa: c.no_wa, alasan: alasan });
} catch (e) {}

console.warn('Follow-up dilewati (' + c.no_wa + '): ' + alasan);
return [{ json: { no_wa: c.no_wa, alasan: alasan } }];

// ====================================================================
// REPORT FU RUN (2026-08-27)
// Dipasang di output "done" Loop Kandidat yang selama ini menganggur.
// DIAM TOTAL kalau tidak ada kegagalan - ini alarm, bukan laporan rutin.
// Tanpa ini, satu lead yang konteksnya selalu bikin AI melanggar akan
// dicoba ulang tiap jam selamanya tanpa ada yang tahu.
// ====================================================================
let gagal = [];
try {
  const sd = $getWorkflowStaticData('global');
  gagal = Array.isArray(sd.fu_ai_fail) ? sd.fu_ai_fail.slice() : [];
  sd.fu_ai_fail = [];
} catch (e) {}

let total = 0;
try { total = $('Filter Kandidat').all().length; } catch (e) {}
let antrian = 0;
try { antrian = Number($('Filter Kandidat').first().json.antrian_total || 0); } catch (e) {}

// Mode uji WAJIB selalu dilaporkan, walau tidak ada kegagalan - kalau lupa
// dikosongkan, follow-up berhenti menjangkau lead sungguhan tanpa gejala apa pun.
let ujiInfo = '';
try {
  const tn = $('Parse Config FU').first().json.config.test_numbers || [];
  if (tn.length) ujiInfo = tn.join(', ');
} catch (e) {}
const modeUji = !!ujiInfo;

// (2026-09-13) Penolakan guard (penanda FU_AI_DITOLAK_GUARD dari "Validate FU Message")
// TIDAK di-rollback ke jadwal lama: "Rollback STATS FU (AI)" menunda nomor itu ke jadwal
// follow-up berikutnya, jadi tidak muncul lagi tiap jam. Gagal teknis (AI/credential)
// tetap di-rollback dan dicoba lagi run berikutnya - teks lamanya dipertahankan.
const isGuard = g => String(g.alasan || '').indexOf('FU_AI_DITOLAK_GUARD') !== -1;
const tampil = g => isGuard(g)
  ? String(g.alasan).replace('FU_AI_DITOLAK_GUARD', 'ditolak guard').replace(/\s*\[line [^\]]*\]\s*$/, '')
  : g.alasan;
const nGuard = gagal.filter(isGuard).length;
const nTeknis = gagal.length - nGuard;
let intervalJam = 0;
try { intervalJam = Number($('Parse Config FU').first().json.config.followup_interval_hours || 0); } catch (e) {}

const baris = gagal.slice(0, 10).map(g => '- ' + g.no_wa + ': ' + tampil(g)).join('\n');
const sisa = gagal.length > 10 ? ('\n... dan ' + (gagal.length - 10) + ' lagi') : '';

const penutup = [];
if (nGuard) {
  penutup.push('Nomor yang "ditolak guard" TIDAK dikirimi pesan dan DITUNDA ke jadwal follow-up berikutnya'
    + (intervalJam ? (' (' + intervalJam + ' jam lagi)') : '') + ', jadi tidak diulang tiap jam.');
}
if (nTeknis) {
  penutup.push((nGuard ? 'Sisanya' : 'Nomor-nomor itu') + ' TIDAK dikirimi pesan dan klaimnya sudah di-rollback, jadi akan dicoba lagi run berikutnya. Kalau nomor yang sama muncul terus tiap jam, konteksnya perlu diperiksa manual.');
}

const infoAntrian = (antrian > total)
  ? (' (cap ' + total + ' per run; antrian layak follow-up masih ' + antrian + ')')
  : '';
const notif_text = '[PCR] FOLLOW-UP AI: ' + gagal.length + ' dari ' + total +
  ' kandidat dilewati' + infoAntrian + '\n\n' + baris + sisa +
  (penutup.length ? ('\n\n' + penutup.join('\n\n')) : '\n\nNomor-nomor itu TIDAK dikirimi pesan dan klaimnya sudah di-rollback, jadi akan dicoba lagi run berikutnya. Kalau nomor yang sama muncul terus tiap jam, konteksnya perlu diperiksa manual.');

const peringatanUji = modeUji
  ? ('\n\nMODE UJI masih AKTIF - hanya ' + ujiInfo + ' yang di-follow-up. '
     + 'Lead sungguhan TIDAK tersentuh. Kosongkan CONFIG followup_test_numbers '
     + 'kalau sudah selesai menguji.')
  : '';

return [{ json: {
  perlu_notif: gagal.length > 0 || modeUji,
  mode_uji: modeUji,
  ada_gagal: gagal.length > 0,
  jumlah_gagal: gagal.length,
  total_kandidat: total,
  notif_text: notif_text + peringatanUji
}}];
